      store_h: "Wo es aufbewahrt wird",
      store_p: "Außer Reichweite und außer Sicht — weit oben, abgeschlossen oder mit Kindersicherung — und immer in der Originalverpackung. Das wiederholt jede einzelne unserer Quellen.",
      store_cite: "NHS — “Poisoning” · SEUP — “Intoxicaciones. Información para padres” · MedlinePlus — “Child Safety” · Junta de Andalucía — “Cuídame: orientaciones para el comienzo de la vida”",
      expiry_h: "Auf das Datum schauen",
      expiry_p: "Rehydratationssalze verfallen wie jedes Medikament. Und wenn jemand im Haus einen Adrenalin-Autoinjektor trägt, wird dessen Datum regelmäßig geprüft und rechtzeitig ersetzt.",
      expiry_cite: "AEMPS — “Sueroral Hiposódico” · NHS — “Anaphylaxis”",
      foot: "Jede hier genannte Quelle steht in unserer Quellenliste, und Sie können sie selbst öffnen.",
      have: [
        { name: "Ein digitales Fieberthermometer", what: "Unter einem Jahr wird rektal gemessen; ab einem Jahr sind andere Stellen zuverlässig. In der Achsel so lange liegen lassen, wie es die Packungsbeilage angibt.", cite: "NHS — “High temperature (fever) in children” · Junta de Andalucía — “Cuídame: guía para madres y padres”" },
        { name: "Orale Rehydratationssalze", what: "Sauberes Wasser, Salz und Zucker; wenige Cent pro Gabe. Nach dem Erbrechen zwanzig Minuten warten und dann kleine Mengen geben.", cite: "WHO — “Diarrhoeal disease” · SEUP — “Vómitos. Información para padres”" },
        { name: "Kochsalzlösung für die Nase", what: "Bei verstopfter Nase: die Nasenlöcher vor dem Essen und vor dem Schlafen sanft spülen.", cite: "NHS — “Respiratory syncytial virus (RSV)” · Junta de Andalucía — “Cuídame: orientaciones para el comienzo de la vida”" },
        { name: "Die Spritze aus der Medikamentenpackung", what: "Immer die Spritze oder den Löffel aus dieser Packung, nie einen Küchenlöffel. Dasselbe Medikament gibt es in verschiedenen Stärken, und nur sein eigenes Maß passt dazu.", cite: "NHS — “Paracetamol for children”" },
        { name: "Paracetamol oder Ibuprofen, nach Gewicht", what: "Nach Gewicht, nicht nach Alter. Auf dieser Seite gibt es einen Rechner, der die veröffentlichte Tabelle benutzt.", cite: "AEPap — “Guía rápida de dosificación práctica en pediatría”" },
      ],
      avoid: [
        { name: "Aspirin, in jedem Alter", what: "Niemals einem Kind: es kann das Reye-Syndrom auslösen, selten aber schwer, das Leber und Gehirn schädigt. Deshalb gibt es keine Kinderpräparate davon.", cite: "CDC — “Ear Infection Basics” · MedlinePlus — “Chickenpox” · AEPap — “Guía rápida de dosificación práctica en pediatría”" },
        { name: "Husten- und Erkältungssäfte", what: "Unter vier Jahren nicht, außer eine Ärztin sagt es ausdrücklich. Codein und Dextromethorphan werden unter zwölf nicht empfohlen: es gibt keinen Beleg, dass sie sicher sind oder wirken.", cite: "CDC — “Ear Infection Basics” · PUC Chile — “Manual de Pediatría”" },
        { name: "Ipecacuanha-Sirup", what: "Bringen Sie ein Kind nicht zum Erbrechen, wenn es etwas verschluckt hat. Ipecacuanha wird dafür nicht mehr verwendet.", cite: "Ecimed — “Pediatría. Diagnóstico y tratamiento”" },
        { name: "Honig, vor dem ersten Geburtstag", what: "Er kann das Bakterium enthalten, das Säuglingsbotulismus verursacht. Ab einem Jahr wird er gegen Husten benutzt.", cite: "MedlinePlus — “Infant and Newborn Nutrition” · CDC — “Manage Common Cold”" },
      ],
